use std::slice;

const QMAX: usize = 32;
const ROOTS: usize = 65;
const ARENA: usize = 16384;
const POOL: usize = 8192;
const LEVELS: usize = 16;
const VMAX: i64 = 1_000_000;
const SUMMAX: i64 = 64_000_000;

#[derive(Clone, Copy, Default)] struct Measure { count: i32, sum: i64 }
#[derive(Clone, Copy, Default)] struct Tree { kind:u8, level:u8, plen:u8, slen:u8, mid:i32, pre:[i32;4], suf:[i32;4], count:i32, sum:i64 }
#[derive(Clone, Copy, Default)] struct Node { arity:u8, child:[i32;3], count:i32, sum:i64 }
#[derive(Clone, Copy, Default)] struct Root { tree:i32, length:i32, sum:i64 }
#[derive(Clone, Copy, Default)] struct View { found:bool, item:i32, tree:i32 }
#[derive(Clone, Copy, Default)] struct Split { found:bool, item:i32, left:i32, right:i32 }
struct Ctx { trees:Vec<Tree>, nodes:Vec<Node>, empty:[i32;LEVELS], failed:bool }
impl Ctx {
    fn new()->Self { Self{trees:Vec::with_capacity(POOL),nodes:Vec::with_capacity(POOL),empty:[-1;LEVELS],failed:false} }
    fn alloc_tree(&mut self)->i32 { if self.trees.len()+self.nodes.len()>=ARENA||self.trees.len()>=POOL {self.failed=true;return 0;} self.trees.push(Tree::default());(self.trees.len()-1) as i32 }
    fn alloc_node(&mut self)->i32 { if self.trees.len()+self.nodes.len()>=ARENA||self.nodes.len()>=POOL {self.failed=true;return 0;} self.nodes.push(Node::default());(self.nodes.len()-1) as i32 }
}
fn addm(a:Measure,b:Measure)->Measure { Measure{count:a.count+b.count,sum:a.sum+b.sum} }
fn refm(c:&Ctx,r:i32)->Measure { if r<0 {Measure{count:1,sum:(-r as i64)-1}} else {let x=c.nodes[r as usize];Measure{count:x.count,sum:x.sum}} }
fn treem(c:&Ctx,r:i32)->Measure {let t=c.trees[r as usize];Measure{count:t.count,sum:t.sum}}
fn empty(c:&mut Ctx,l:u8)->i32 { if l as usize>=LEVELS {c.failed=true;return 0;}let k=l as usize;if c.empty[k]>=0{return c.empty[k];}let id=c.alloc_tree();let mut t=Tree::default();t.level=l;t.kind=0;t.mid=-1;c.trees[id as usize]=t;c.empty[k]=id;id }
fn single(c:&mut Ctx,l:u8,x:i32)->i32 {let id=c.alloc_tree();let m=refm(c,x);let mut t=Tree::default();t.kind=1;t.level=l;t.plen=1;t.pre[0]=x;t.count=m.count;t.sum=m.sum;c.trees[id as usize]=t;id}
fn node(c:&mut Ctx,x:&[i32],n:u8)->i32 {let id=c.alloc_node();let mut z=Node::default();z.arity=n;let mut m=Measure::default();for i in 0..n as usize{z.child[i]=x[i];m=addm(m,refm(c,x[i]));}z.count=m.count;z.sum=m.sum;c.nodes[id as usize]=z;id}
fn deep(c:&mut Ctx,l:u8,p:&[i32],pn:u8,mid:i32,s:&[i32],sn:u8)->i32 {if pn==0||sn==0{c.failed=true;return empty(c,l);}let id=c.alloc_tree();let mut t=Tree::default();t.kind=2;t.level=l;t.plen=pn;t.slen=sn;t.mid=mid;let mut m=treem(c,mid);for i in 0..pn as usize{t.pre[i]=p[i];m=addm(m,refm(c,p[i]));}for i in 0..sn as usize{t.suf[i]=s[i];m=addm(m,refm(c,s[i]));}t.count=m.count;t.sum=m.sum;c.trees[id as usize]=t;id}
fn from_items(c:&mut Ctx,l:u8,x:&[i32],n:u8)->i32 {let mut r=empty(c,l);for i in 0..n as usize{r=snoc(c,l,r,x[i]);}r}
fn cons(c:&mut Ctx,l:u8,x:i32,id:i32)->i32 {let t=c.trees[id as usize];if t.kind==0{return single(c,l,x);}if t.kind==1{let m=empty(c,l+1);return deep(c,l,&[x],1,m,&[t.pre[0]],1);}if t.plen<4{let mut p=[0;4];p[0]=x;for i in 0..t.plen as usize{p[i+1]=t.pre[i];}return deep(c,l,&p,t.plen+1,t.mid,&t.suf,t.slen);}let g=[t.pre[1],t.pre[2],t.pre[3]];let n=node(c,&g,3);let middle=cons(c,l+1,n,t.mid);deep(c,l,&[x,t.pre[0]],2,middle,&t.suf,t.slen)}
fn snoc(c:&mut Ctx,l:u8,id:i32,x:i32)->i32 {let t=c.trees[id as usize];if t.kind==0{return single(c,l,x);}if t.kind==1{let m=empty(c,l+1);return deep(c,l,&[t.pre[0]],1,m,&[x],1);}if t.slen<4{let mut s=t.suf;s[t.slen as usize]=x;return deep(c,l,&t.pre,t.plen,t.mid,&s,t.slen+1);}let g=[t.suf[0],t.suf[1],t.suf[2]];let n=node(c,&g,3);let middle=snoc(c,l+1,t.mid,n);deep(c,l,&t.pre,t.plen,middle,&[t.suf[3],x],2)}
fn viewl(c:&mut Ctx,l:u8,id:i32)->View {let t=c.trees[id as usize];if t.kind==0{return View{found:false,item:0,tree:id};}if t.kind==1{return View{found:true,item:t.pre[0],tree:empty(c,l)};}let x=t.pre[0];let r=if t.plen>1{deep(c,l,&t.pre[1..],t.plen-1,t.mid,&t.suf,t.slen)}else{let v=viewl(c,l+1,t.mid);if !v.found{from_items(c,l,&t.suf,t.slen)}else{let n=c.nodes[v.item as usize];deep(c,l,&n.child,n.arity,v.tree,&t.suf,t.slen)}};View{found:true,item:x,tree:r}}
fn viewr(c:&mut Ctx,l:u8,id:i32)->View {let t=c.trees[id as usize];if t.kind==0{return View{found:false,item:0,tree:id};}if t.kind==1{return View{found:true,item:t.pre[0],tree:empty(c,l)};}let x=t.suf[t.slen as usize-1];let r=if t.slen>1{deep(c,l,&t.pre,t.plen,t.mid,&t.suf[..t.slen as usize-1],t.slen-1)}else{let v=viewr(c,l+1,t.mid);if !v.found{from_items(c,l,&t.pre,t.plen)}else{let n=c.nodes[v.item as usize];deep(c,l,&t.pre,t.plen,v.tree,&n.child,n.arity)}};View{found:true,item:x,tree:r}}
fn deep_l(c:&mut Ctx,l:u8,p:&[i32],pn:u8,m:i32,s:&[i32],sn:u8)->i32 {if pn>0{return deep(c,l,p,pn,m,s,sn);}let v=viewl(c,l+1,m);if !v.found{return from_items(c,l,s,sn);}let n=c.nodes[v.item as usize];deep(c,l,&n.child,n.arity,v.tree,s,sn)}
fn deep_r(c:&mut Ctx,l:u8,p:&[i32],pn:u8,m:i32,s:&[i32],sn:u8)->i32 {if sn>0{return deep(c,l,p,pn,m,s,sn);}let v=viewr(c,l+1,m);if !v.found{return from_items(c,l,p,pn);}let n=c.nodes[v.item as usize];deep(c,l,p,pn,v.tree,&n.child,n.arity)}
fn group(c:&mut Ctx,l:u8,x:&[i32],n:u8,out:&mut [i32;8])->u8 {let mut k=0u8;let mut p=0u8;while p<n{let rem=n-p;let take=if rem==2||rem==4{2}else{3};if rem==1{c.failed=true;return k;}out[k as usize]=node(c,&x[p as usize..],take);k+=1;p+=take;}k}
fn append3(c:&mut Ctx,l:u8,a:i32,x:&[i32],xn:u8,b:i32)->i32 {let A=c.trees[a as usize];let B=c.trees[b as usize];if A.kind==0{let mut r=b;for i in (0..xn as usize).rev(){r=cons(c,l,x[i],r);}return r;}if B.kind==0{let mut r=a;for i in 0..xn as usize{r=snoc(c,l,r,x[i]);}return r;}if A.kind==1{let mut r=b;for i in (0..xn as usize).rev(){r=cons(c,l,x[i],r);}return cons(c,l,A.pre[0],r);}if B.kind==1{let mut r=a;for i in 0..xn as usize{r=snoc(c,l,r,x[i]);}return snoc(c,l,r,B.pre[0]);}let mut all=[0;16];let mut n=0usize;for i in 0..A.slen as usize{all[n]=A.suf[i];n+=1;}for i in 0..xn as usize{all[n]=x[i];n+=1;}for i in 0..B.plen as usize{all[n]=B.pre[i];n+=1;}let mut ns=[0;8];let nn=group(c,l,&all,n as u8,&mut ns);let m=append3(c,l+1,A.mid,&ns,nn,B.mid);deep(c,l,&A.pre,A.plen,m,&B.suf,B.slen)}
fn pred(mode:u8,target:i64,m:Measure)->bool {if mode==0{m.count as i64>target}else{m.sum>=target}}
fn split_tree(c:&mut Ctx,id:i32,acc:Measure,mode:u8,target:i64)->Split {let t=c.trees[id as usize];if t.kind==0{return Split{found:false,item:0,left:0,right:id};}if t.kind==1{if pred(mode,target,addm(acc,refm(c,t.pre[0]))){let e=empty(c,t.level);return Split{found:true,item:t.pre[0],left:e,right:e};}return Split{found:false,item:0,left:id,right:empty(c,t.level)};}let mut cur=acc;for i in 0..t.plen as usize{cur=addm(cur,refm(c,t.pre[i]));if pred(mode,target,cur){let l=from_items(c,t.level,&t.pre,(i) as u8);let r=deep_l(c,t.level,&t.pre[i+1..],t.plen-(i as u8)-1,t.mid,&t.suf,t.slen);return Split{found:true,item:t.pre[i],left:l,right:r};}}let mut ap=acc;for i in 0..t.plen as usize{ap=addm(ap,refm(c,t.pre[i]));}let mid=treem(c,t.mid);let through=addm(ap,mid);if pred(mode,target,through){let sm=split_tree(c,t.mid,ap,mode,target);if !sm.found{c.failed=true;return Split{found:false,item:0,left:id,right:empty(c,t.level)};}let nd=c.nodes[sm.item as usize];let mut ca=addm(ap,treem(c,sm.left));let mut before=[0;3];let mut after=[0;3];let mut nb=0usize;let mut na=0usize;let mut pivot=0;let mut found=false;for i in 0..nd.arity as usize{let next=addm(ca,refm(c,nd.child[i]));if !found&&pred(mode,target,next){pivot=nd.child[i];found=true;}else if !found{before[nb]=nd.child[i];nb+=1;ca=next;}else{after[na]=nd.child[i];na+=1;}}if !found{c.failed=true;return Split{found:false,item:0,left:id,right:empty(c,t.level)};}return Split{found:true,item:pivot,left:deep_r(c,t.level,&t.pre,t.plen,sm.left,&before,nb as u8),right:deep_l(c,t.level,&after,na as u8,sm.right,&t.suf,t.slen)};}cur=through;let mut before=[0;4];for i in 0..t.slen as usize{cur=addm(cur,refm(c,t.suf[i]));if pred(mode,target,cur){let l=deep_r(c,t.level,&t.pre,t.plen,t.mid,&before,i as u8);let r=from_items(c,t.level,&t.suf[i+1..],t.slen-(i as u8)-1);return Split{found:true,item:t.suf[i],left:l,right:r};}before[i]=t.suf[i];}Split{found:false,item:0,left:id,right:empty(c,t.level)}}
fn item_value(x:i32)->i64{-(x as i64)-1}
fn store(out:*mut u8,offset:usize,value:i64){let bits=value as u64;for i in 0..8{unsafe{*out.add(offset+i)=(bits>>(8*i)) as u8;}}}

#[no_mangle]
pub unsafe extern "C" fn measured_finger_tree_sequence(input:*const i64,length:usize,output:*mut u8,capacity:usize)->i64 {
    if input.is_null()||length<2||length>195{return -1;}let v=slice::from_raw_parts(input,length);let n0=v[0];if !(0..=32).contains(&n0){return -1;}let n=n0 as usize;if length<n+2{return -1;}let qv=v[n+1];if !(1..=32).contains(&qv){return -1;}let q=qv as usize;if length!=n+2+5*q||length>194{return -1;}
    let mut c=Ctx::new();let mut t=empty(&mut c,0);for i in 0..n{let x=v[1+i];if !(0..=VMAX).contains(&x){return -1;}t=snoc(&mut c,0,t,(-x-1) as i32);}if c.failed{return -1;}let m=treem(&c,t);if m.count>64||m.sum>SUMMAX{return -1;}let mut roots=[Root::default();ROOTS];roots[0]=Root{tree:t,length:m.count,sum:m.sum};let mut nr=1usize;let mut at=n+2;let mut records=[0i64;QMAX*7];
    for op in 0..q{let tag=v[at];let aa=v[at+1];let bb=v[at+2];let x=v[at+3];let y=v[at+4];at+=5;if !(0..=6).contains(&tag)||aa<0||aa as usize>=nr||nr>=ROOTS{return -1;}let a=aa as usize;let src=roots[a].tree;let mut res=0;let mut res2=0;let mut right=-1i32;let mut aux=-1i64;let mut two=false;
        if tag<=1{if bb!=-1||y!=-1||!(0..=VMAX).contains(&x)||roots[a].length>=64||roots[a].sum+x>SUMMAX{return -1;}let item=(-x-1) as i32;res=if tag==0{cons(&mut c,0,item,src)}else{snoc(&mut c,0,src,item)};}
        else if tag<=3{if bb!=-1||x!=-1||y!=-1||roots[a].length==0{return -1;}let z=if tag==2{viewl(&mut c,0,src)}else{viewr(&mut c,0,src)};if !z.found{return -1;}res=z.tree;aux=item_value(z.item);}
        else if tag==4{if bb<0||bb as usize>=nr||x!=-1||y!=-1{return -1;}let b=bb as usize;if roots[a].length+roots[b].length>64||roots[a].sum+roots[b].sum>SUMMAX{return -1;}res=append3(&mut c,0,src,&[],0,roots[b].tree);}
        else{if bb!=-1||y!=-1||(tag==5&&(x<0||x>roots[a].length as i64))||(tag==6&&(x<1||x>SUMMAX)){return -1;}let s=split_tree(&mut c,src,Measure::default(),if tag==5{0}else{1},x);if s.found{if tag==5{res=s.left;res2=cons(&mut c,0,s.item,s.right);aux=x;}else{res=snoc(&mut c,0,s.left,s.item);res2=s.right;aux=treem(&c,res).count as i64;}}else{res=src;res2=empty(&mut c,0);aux=if tag==5{x}else{-1};}two=true;}
        if c.failed{return -1;}let lm=treem(&c,res);if lm.count>64||lm.sum>SUMMAX{return -1;}let left=nr as i32;roots[nr]=Root{tree:res,length:lm.count,sum:lm.sum};nr+=1;let mut rl=-1i32;let mut rs=-1i64;if two{if nr>=ROOTS{return -1;}let rm=treem(&c,res2);if rm.count>64||rm.sum>SUMMAX{return -1;}right=nr as i32;rl=rm.count;rs=rm.sum;roots[nr]=Root{tree:res2,length:rm.count,sum:rm.sum};nr+=1;}let o=op*7;records[o]=left as i64;records[o+1]=lm.count as i64;records[o+2]=lm.sum;records[o+3]=right as i64;records[o+4]=rl as i64;records[o+5]=rs;records[o+6]=aux;
    }
    let bytes=56*q;if output.is_null()||capacity<bytes{return -2;}let mut staged=[0u8;1792];for i in 0..q*7{store(staged.as_mut_ptr(),8*i,records[i]);}for i in 0..bytes{unsafe{*output.add(i)=staged[i];}}bytes as i64
}
